// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX3} from "../src/MultiplicatorX3.sol";

contract InvMutTest is Test {
    MultiplicatorX3 c;
    function setUp() public { c = new MultiplicatorX3(); }
    function testFuzz_property(uint256 amount, bytes calldata data) public {
        vm.assume(amount > 0);
        vm.assume(amount <= address(this).balance);
        Helper h = new Helper();
        vm.deal(address(this), amount);
        c.Command{value: amount}(address(h), data);
        assertTrue(h.received() == amount);
    }
}

contract Helper {
    uint256 public received;
    fallback() external payable { received = msg.value; }
}
